            "neutral_cells",
            "enemy_cells",
            "opponent_territory",
            "border_cells",
            "frontier_cells",
            "capture_targets",
        )
        target = nearest(targets, self_pos)
        if target is not None:
            move = step_toward(self_pos, target)
            if move == [0, 0]:
